// ── Build job packages (Phase 1: code-only + selective AI) ───────────────────
// Reads ALL rows from upstream Read nodes.
// Skips AI for: completed date, code blockers, frozen handover jobs.
// AI only for ambiguous jobs (no Completed date, no blockers, inputs changed).

function norm(v) { return String(v !== null && v !== undefined ? v : '').trim(); }
function normKey(s) { return norm(s).toUpperCase(); }

function colVal(row, prefix) {
  const keys = Object.keys(row || {});
  const exact = keys.find(function (k) { return k === prefix; });
  if (exact != null && norm(row[exact])) return norm(row[exact]);
  const p = String(prefix || '').toLowerCase();
  for (let i = 0; i < keys.length; i++) {
    const k = keys[i];
    if (k.toLowerCase().indexOf(p) === 0 && norm(row[k])) return norm(row[k]);
  }
  return '';
}

function isReadyToHandover(row) {
  const keys = Object.keys(row || {});
  for (let i = 0; i < keys.length; i++) {
    const k = keys[i];
    if (/^ready to hand/i.test(k)) {
      const v = norm(row[k]).toLowerCase();
      if (v === 'yes' || v === 'y' || v === 'true') return true;
    }
  }
  return false;
}

function parseDateCreated(s) {
  const t = norm(s);
  if (!t) return '';
  if (/^\d{4}-\d{2}-\d{2}/.test(t)) return t.slice(0, 10);
  const m = t.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})/);
  if (!m) return t;
  let y = m[3];
  if (y.length === 2) y = '20' + y;
  const pad = function (n) { return n.length < 2 ? '0' + n : n; };
  return y + '-' + pad(m[2]) + '-' + pad(m[1]);
}

function parseApptDate(s) {
  const t = norm(s);
  if (!t) return '';
  if (/^\d{4}-\d{2}-\d{2}/.test(t)) return t.slice(0, 10);
  const m = t.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})/);
  if (!m) return '';
  let a = parseInt(m[1], 10), b = parseInt(m[2], 10), y = m[3];
  if (y.length === 2) y = '20' + y;
  y = parseInt(y, 10);
  let mo, day;
  if (a > 12) { day = a; mo = b; }
  else if (b > 12) { mo = a; day = b; }
  else { mo = a; day = b; }
  const pad = function (n) { return n < 10 ? '0' + n : String(n); };
  return y + '-' + pad(mo) + '-' + pad(day);
}

function isHeader(row) {
  return /^smartform name$/i.test(norm(row['SmartForm Name'] || row.smart_form_name));
}

function parseHours(raw) {
  const s = norm(raw);
  if (!s) return 0;
  const m = s.match(/(\d+(?:\.\d+)?)/);
  return m ? parseFloat(m[1]) : 0;
}

function parseMinutes(raw) {
  const n = parseFloat(String(raw !== null && raw !== undefined ? raw : '').replace(/[^0-9.]/g, ''));
  return Number.isFinite(n) ? n : null;
}

function isQ22No(val) {
  const s = norm(val).toLowerCase();
  if (!s) return false;
  return s === 'no' || s === 'n' || /^no\b/.test(s) || s === 'false' || /not answered/i.test(s) || /partial/i.test(s);
}

function isBccTrackerComplete(val) {
  const s = norm(val).toLowerCase();
  if (!s) return false;
  return s === 'complete' || s === 'completed' || s.startsWith('complete');
}

function isQ22Yes(val) {
  const s = norm(val).toLowerCase();
  if (!s) return false;
  return s === 'yes' || s === 'y' || /^yes\b/.test(s) || s === 'true';
}

function hasOutstandingNotes(val) {
  const s = norm(val).toLowerCase();
  if (!s) return false;
  const cues = [
    'need to return', 'return to', 'outstanding', 'not complete', 'incomplete',
    'need time', 'follow up', 'follow-up', 'revisit', 'to be done', 'still need',
    'extra coat', 'second coat', '2 coats', 'two coats', 'awaiting', 'will return', 'come back',
    'as an extra', 'coat to dry', 'each coat', 'stain block', 'pluss', 'plus coat', 'drying time'
  ];
  for (let i = 0; i < cues.length; i++) {
    if (s.indexOf(cues[i]) >= 0) return true;
  }
  return false;
}

function computeCompletionBlockers(visits) {
  const blockers = [];
  if (!visits.length) return blockers;

  const chrono = visits.slice().sort(function (a, b) {
    return parseDateCreated(a.date_created).localeCompare(parseDateCreated(b.date_created));
  });
  const latest = chrono[chrono.length - 1] || {};

  if (isQ22No(latest.q22_complete)) {
    blockers.push('Latest visit Q2.2: operative did not complete work in full (' + norm(latest.q22_complete) + ')');
  } else if (!isQ22Yes(latest.q22_complete)) {
    blockers.push('Latest visit Q2.2 is not Yes — work in full not confirmed (' + (norm(latest.q22_complete) || 'blank') + ')');
  }

  if (hasOutstandingNotes(latest.q31_notes)) {
    blockers.push('Latest visit Q3.1 notes indicate outstanding work: ' + latest.q31_notes.slice(0, 160));
  }

  let openQ22No = false;
  for (let i = 0; i < chrono.length; i++) {
    if (isQ22No(chrono[i].q22_complete)) openQ22No = true;
    else if (isQ22Yes(chrono[i].q22_complete)) openQ22No = false;
  }
  if (openQ22No && !blockers.some(function (b) { return b.indexOf('Q2.2') >= 0; })) {
    blockers.push('A visit recorded Q2.2 No without a later Yes');
  }

  for (let i = 0; i < chrono.length; i++) {
    const v = chrono[i];
    if (hasOutstandingNotes(v.q31_notes)) {
      blockers.push('Q3.1 notes indicate outstanding work: ' + v.q31_notes.slice(0, 160));
      break;
    }
  }
  if (!blockers.some(function (b) { return b.indexOf('Q3.1') >= 0; })) {
    for (let i = 0; i < chrono.length; i++) {
      const v = chrono[i];
      if (norm(v.q25_why_not)) {
        blockers.push('Q2.5 reason not complete: ' + v.q25_why_not.slice(0, 160));
        break;
      }
      if (hasOutstandingNotes(v.q28_outstanding)) {
        blockers.push('Q2.8 outstanding works: ' + v.q28_outstanding.slice(0, 160));
        break;
      }
    }
  }

  return blockers;
}

function jobKeyFromRow(row) {
  const sfn = norm(row['SmartForm Name'] || row.smart_form_name);
  if (sfn) return normKey(sfn);
  const corf = norm(row.CORF || row.corf);
  return corf ? 'CORF:' + corf : '';
}

function isRealBoqRow(r) {
  const rt = norm(r['Row Type'] || r.Row_Type || r.row_type);
  if (rt === 'sor_line') return true;
  const sor = norm(r['SOR Code'] || r.sor_code);
  return sor && !/^(no_sor_lines|fetch_error)$/i.test(sor);
}

function computeJeopardy(job) {
  if (job.job_status === 'completed') {
    return { in_jeopardy: false, jeopardy_type: '', jeopardy_reason: '' };
  }
  const apptDate = norm(job.appointment_date);
  if (!apptDate) {
    return { in_jeopardy: false, jeopardy_type: '', jeopardy_reason: '' };
  }
  const today = new Date().toISOString().slice(0, 10);
  const nextApptRaw = norm(job.next_appointment_date);
  const nextApptBlank = !nextApptRaw;
  const nextApptIso = nextApptRaw ? parseApptDate(nextApptRaw) : '';
  const nextApptPast = !nextApptBlank && nextApptIso && nextApptIso < today;
  if (nextApptBlank || nextApptPast) {
    const reason = nextApptBlank
      ? 'No next appointment date booked — job requires a new appointment'
      : 'Next appointment date (' + nextApptRaw + ') is in the past — requires action';
    return { in_jeopardy: true, jeopardy_type: 'next_appointment_needed', jeopardy_reason: reason };
  }
  const spent = Number(job.time_spent_hours) || 0;
  const allowed = job.smv_allowed_hours != null && job.smv_allowed_hours !== ''
    ? Number(job.smv_allowed_hours)
    : (job.smv_allowed_minutes != null && job.smv_allowed_minutes !== ''
      ? Number(job.smv_allowed_minutes) / 60
      : null);
  if (allowed && allowed > 0 && spent > allowed * 1.05) {
    return {
      in_jeopardy: true,
      jeopardy_type: 'manager_review',
      jeopardy_reason: 'Time spent exceeds SMV allowance (' + spent + 'h vs ' + allowed + 'h)',
    };
  }
  return { in_jeopardy: false, jeopardy_type: '', jeopardy_reason: '' };
}

function inputFingerprint(job) {
  const parts = [
    job.completed_date || '',
    job.bcc_tracker_status || '',
    (job.completion_blockers || []).join('|'),
    String(job.visit_count || 0),
    String(job.time_spent_hours || 0),
    job.appointment_date || '',
    job.next_appointment_date || '',
    job.latest_q22 || '',
    job.latest_q31 || '',
    String(job.boq_line_count || 0),
    (job.boq_descriptions_text || '').slice(0, 400),
    (job.all_q21_text || '').slice(0, 400),
  ];
  return parts.join('::');
}

function computeCodeOnlyStatus(job) {
  const completedDate = norm(job.completed_date);
  const blockers = job.completion_blockers || [];
  const forceIncomplete = blockers.length > 0;
  const sheetStatus = norm(job.sheet_job_status).toLowerCase();
  const sheetNotes = norm(job.sheet_status_notes);

  if (completedDate) {
    return {
      job_status: 'completed',
      job_status_reason: 'Works completed date: ' + completedDate,
      job_status_confidence: 'high',
      uncovered_items: '',
      time_assessment_notes: '',
      ojs_scope_complete: false,
    };
  }
  if (isBccTrackerComplete(job.bcc_tracker_status)) {
    const bccLabel = norm(job.bcc_tracker_status) || 'Complete';
    return {
      job_status: 'completed',
      job_status_reason: 'BCC Tracker Status: ' + bccLabel + ' (completed date not set yet)',
      job_status_confidence: 'high',
      uncovered_items: '',
      time_assessment_notes: '',
      ojs_scope_complete: false,
    };
  }
  if (forceIncomplete) {
    return {
      job_status: 'incomplete',
      job_status_reason: blockers.join('; '),
      job_status_confidence: 'high',
      uncovered_items: '',
      time_assessment_notes: '',
      ojs_scope_complete: false,
    };
  }
  if (sheetStatus === 'completed' && /ojs scope/i.test(sheetNotes)) {
    return {
      job_status: 'completed',
      job_status_reason: sheetNotes || 'OJS scope appears complete (no EasyBOP completed date yet)',
      job_status_confidence: 'medium',
      uncovered_items: '',
      time_assessment_notes: '',
      ojs_scope_complete: true,
    };
  }
  return {
    job_status: 'incomplete',
    job_status_reason: 'No completed date — job is WIP',
    job_status_confidence: 'medium',
    uncovered_items: '',
    time_assessment_notes: '',
    ojs_scope_complete: false,
  };
}

function buildCodeResult(job) {
  const codeStatus = computeCodeOnlyStatus(job);
  const merged = Object.assign({}, job, codeStatus);
  const jeopardy = computeJeopardy(merged);
  merged.in_jeopardy = jeopardy.in_jeopardy;
  merged.jeopardy_reason = jeopardy.jeopardy_reason;
  merged._jeopardy = jeopardy;
  merged.processed_via = 'code_only';
  return merged;
}

// Pull ALL rows directly from Read nodes
const ojsItems = $('Read Operative Job Sheet7').all();
const boqItems = $('Read OJS BOQ & SMV2').all();
const ojsRows = ojsItems.map(function(i) { return i.json || {}; });
const boqRows = boqItems.map(function(i) { return i.json || {}; });

const jobs = new Map();

function ensureJob(key, sample) {
  if (!jobs.has(key)) {
    jobs.set(key, {
      job_key: key,
      smart_form_name: norm(sample['SmartForm Name'] || sample.smart_form_name),
      corf: norm(sample.CORF || sample.corf),
      boq_lines: [],
      visits: [],
      ready_to_handover: false,
      sheet_job_status: '',
      sheet_status_notes: '',
      sheet_input_hash: '',
      sheet_checked_at: '',
      bcc_tracker_status: '',
    });
  }
  return jobs.get(key);
}

for (const row of boqRows) {
  if (isHeader(row)) continue;
  const key = jobKeyFromRow(row);
  if (!key || !isRealBoqRow(row)) continue;
  const job = ensureJob(key, row);
  job.boq_lines.push({
    sor_code: norm(row['SOR Code'] || row.sor_code),
    description: norm(row.Description || row.description),
    line_minutes: parseMinutes(row['Line Minutes'] || row.line_minutes),
    smv_raw: norm(row['SMV Raw'] || row.smv_raw),
    qty: row.Qty || row.qty,
  });
  const jm = parseMinutes(row['Job Estimated Minutes'] || row.job_estimated_minutes);
  const jh = parseMinutes(row['Job Estimated Hours'] || row.job_estimated_hours);
  if (jm !== null) job.smv_allowed_minutes = jm;
  if (jh !== null) job.smv_allowed_hours = jh;
}

for (const row of ojsRows) {
  if (isHeader(row)) continue;
  const name = norm(row['SmartForm Name'] || row.smart_form_name);
  if (!name) continue;
  const key = jobKeyFromRow(row);
  if (!key) continue;
  const job = ensureJob(key, row);
  if (isReadyToHandover(row)) job.ready_to_handover = true;
  if (!job.sheet_job_status && norm(row['Job Status'])) job.sheet_job_status = norm(row['Job Status']);
  if (!job.sheet_status_notes && norm(row['Job Status Notes'])) job.sheet_status_notes = norm(row['Job Status Notes']);
  if (!job.sheet_input_hash && norm(row['Job Status Input Hash'])) job.sheet_input_hash = norm(row['Job Status Input Hash']);
  if (!job.sheet_checked_at && norm(row['Job Status Checked At'])) job.sheet_checked_at = norm(row['Job Status Checked At']);
  const hrs = parseHours(colVal(row, 'Q2.1 Daily Jobs Table Price/Hours'));
  const op = norm(row['Created By'] || row.created_by) || 'Unknown';
  job.visits.push({
    row_number: row.row_number,
    date_created: norm(row['Date Created'] || row.date_created),
    created_by: op,
    visit_hours: hrs,
    q21_description: colVal(row, 'Q2.1 Daily Jobs Table'),
    q22_complete: colVal(row, 'Q2.2'),
    q31_notes: colVal(row, 'Q3.1'),
    q25_why_not: colVal(row, 'Q2.5'),
    q28_outstanding: colVal(row, 'Q2.8'),
    appointment_date: norm(row['Appointment Date'] || row.appointment_date || ''),
    next_appointment_date: norm(row['Next appointment date'] || row.next_appointment_date || ''),
    completed_date: norm(row['Completed'] || row.completed || ''),
    bcc_tracker_status: colVal(row, 'BCC Tracker Status'),
    status: norm(row.Status),
  });
}

for (const job of jobs.values()) {
  let totalLineMins = 0;
  for (const bl of job.boq_lines) {
    if (bl.line_minutes !== null) totalLineMins += bl.line_minutes;
  }
  if ((job.smv_allowed_minutes === null || job.smv_allowed_minutes === undefined) && totalLineMins > 0) {
    job.smv_allowed_minutes = totalLineMins;
    job.smv_allowed_hours = Math.round((totalLineMins / 60) * 100) / 100;
  } else if (job.smv_allowed_minutes !== null && job.smv_allowed_minutes !== undefined && (job.smv_allowed_hours === null || job.smv_allowed_hours === undefined)) {
    job.smv_allowed_hours = Math.round((job.smv_allowed_minutes / 60) * 100) / 100;
  }

  const byOp = {};
  let totalHrs = 0;
  for (const v of job.visits) {
    totalHrs += v.visit_hours;
    byOp[v.created_by] = (byOp[v.created_by] || 0) + v.visit_hours;
  }
  job.time_spent_hours = Math.round(totalHrs * 100) / 100;
  job.operative_breakdown = Object.keys(byOp).map(function (name) {
    return name + ': ' + byOp[name] + 'h';
  }).join('; ');

  const allowed = job.smv_allowed_hours || (job.smv_allowed_minutes ? job.smv_allowed_minutes / 60 : null);
  if (allowed === null || allowed === 0) {
    job.time_vs_smv_prelim = 'SMV unknown';
  } else if (totalHrs <= allowed * 1.25) {
    job.time_vs_smv_prelim = totalHrs < allowed * 0.5 ? 'Under SMV' : 'Within allowance';
  } else {
    job.time_vs_smv_prelim = 'Over SMV';
  }
  job.visit_count = job.visits.length;
  job.boq_line_count = job.boq_lines.length;
  job.all_q22_text = job.visits.map(function (v) {
    return (v.date_created ? v.date_created + ': ' : '') + (v.q22_complete || '(blank)');
  }).join('\n');
  job.all_q31_text = job.visits.map(function (v) {
    return (v.date_created ? v.date_created + ': ' : '') + (v.q31_notes || '(blank)');
  }).filter(function (s) { return s.indexOf('(blank)') < 0; }).join('\n---\n');
  job.all_q25_text = job.visits.map(function (v) { return v.q25_why_not; }).filter(Boolean).join('\n---\n');
  job.all_q28_text = job.visits.map(function (v) { return v.q28_outstanding; }).filter(Boolean).join('\n---\n');
  const chronoVisits = job.visits.slice().sort(function (a, b) {
    return parseDateCreated(a.date_created).localeCompare(parseDateCreated(b.date_created));
  });
  const latestVisit = chronoVisits[chronoVisits.length - 1] || {};
  job.latest_q22 = norm(latestVisit.q22_complete);
  job.latest_q31 = norm(latestVisit.q31_notes);
  job.completion_blockers = computeCompletionBlockers(job.visits);
  job.force_incomplete = job.completion_blockers.length > 0;
  job.q22_confirms_complete = isQ22Yes(job.latest_q22);
  let jCompletedDate = '';
  let jNextApptDate = '';
  let jApptDate = '';
  for (let vi = 0; vi < job.visits.length; vi++) {
    const vv = job.visits[vi];
    if (vv.completed_date) jCompletedDate = vv.completed_date;
    if (vv.next_appointment_date) jNextApptDate = vv.next_appointment_date;
    if (vv.appointment_date && !jApptDate) jApptDate = vv.appointment_date;
  }
  job.completed_date = jCompletedDate;
  let jBccTracker = '';
  for (let vi2 = 0; vi2 < job.visits.length; vi2++) {
    const bt = norm(job.visits[vi2].bcc_tracker_status);
    if (bt) jBccTracker = bt;
  }
  job.bcc_tracker_status = jBccTracker;
  job.next_appointment_date = jNextApptDate;
  job.appointment_date = jApptDate;
  job.boq_descriptions_text = job.boq_lines.map(function (l) { return l.description; }).filter(Boolean).join('\n');
  job.boq_sor_codes_text = job.boq_lines.map(function (l) { return l.sor_code; }).filter(Boolean).join(', ');
  job.all_q21_text = job.visits.map(function (v) { return v.q21_description; }).filter(Boolean).join('\n---\n');
  job.input_fingerprint = inputFingerprint(job);
}

const sd = $getWorkflowStaticData('global');
sd._jobPackagesByKey = {};
sd._jobStatusResultsByKey = {};

const aiOut = [];
let skippedCount = 0;
let codeOnlyCount = 0;

for (const job of jobs.values()) {
  if (!job.visits.length) continue;

  const fp = job.input_fingerprint;
  const sheetHash = norm(job.sheet_input_hash);
  const sheetChecked = !!norm(job.sheet_checked_at);
  const hasCompletedDate = !!norm(job.completed_date);
  const hasBlockers = job.force_incomplete;
  const bccTrackerComplete = isBccTrackerComplete(job.bcc_tracker_status);
  job.skip_job = hasCompletedDate && job.ready_to_handover && fp === sheetHash && sheetChecked;
  job.needs_ai = !job.skip_job && !hasCompletedDate && !hasBlockers && !bccTrackerComplete
    && (fp !== sheetHash || !sheetChecked);

  sd._jobPackagesByKey[job.job_key] = job;

  if (job.skip_job) {
    skippedCount++;
    continue;
  }

  const codeResult = buildCodeResult(job);
  sd._jobStatusResultsByKey[job.job_key] = codeResult;
  codeOnlyCount++;

  if (job.needs_ai) {
    aiOut.push({ json: job });
  }
}

sd._buildStats = {
  total_jobs: Object.keys(sd._jobPackagesByKey).length,
  skipped_count: skippedCount,
  code_only_count: codeOnlyCount,
  ai_count: aiOut.length,
};

sd._jobStatusRun = {
  expected: aiOut.length,
  results: [],
};

if (!Object.keys(sd._jobPackagesByKey).length) {
  return [{ json: {
    _diagnostic: true,
    message: 'No jobs with visit rows found',
    ojs_rows_read: ojsRows.length,
    boq_rows_read: boqRows.length,
  }}];
}

// No AI jobs — loop exits immediately; code-only results already in static data
if (aiOut.length === 0) {
  return [];
}

return aiOut;

