  const nextApptBlank = !nextApptRaw;
  const nextApptIso = nextApptRaw ? parseApptDate(nextApptRaw) : '';
  const nextApptPast = !nextApptBlank && nextApptIso && nextApptIso < today;
  // Jeopardy type 1: Next Appointment Needed
  if (nextApptBlank || nextApptPast) {
    const reason = nextApptBlank
      ? 'No next appointment date booked — job requires a new appointment'
      : 'Next appointment date (' + nextApptRaw + ') is in the past — requires action';
    return { in_jeopardy: true, jeopardy_type: 'next_appointment_needed', jeopardy_reason: reason };
  }
  // Jeopardy type 2: Manager Review (time over SMV)
  const spent = Number(job.time_spent_hours) || 0;
  const allowed = job.smv_allowed_hours != null && job.smv_allowed_hours !== ''
    ? Number(job.smv_allowed_hours)
    : (job.smv_allowed_minutes != null && job.smv_allowed_minutes !== ''
      ? Number(job.smv_allowed_minutes) / 60
      : null);
  if (allowed && allowed > 0 && spent > allowed * 1.05) {
    return {
      in_jeopardy: true,
      jeopardy_type: 'manager_review',
      jeopardy_reason: 'Time spent exceeds SMV allowance (' + spent + 'h vs ' + allowed + 'h)',
    };
  }
  return { in_jeopardy: false, jeopardy_type: '', jeopardy_reason: '' };
}

const LOOP_NAMES = ['Loop Over Items1', 'Loop Over Items'];

function parseAi(raw) {
  const aiContent = raw.output && raw.output[0] && raw.output[0].content && raw.output[0].content[0]
    ? raw.output[0].content[0].text
    : (raw.message && raw.message.content ? raw.message.content : raw);
  if (typeof aiContent === 'string') {
    try { return JSON.parse(aiContent); } catch (e) { return {}; }
  }
  if (aiContent && typeof aiContent === 'object') return aiContent;
  return {};
}

function getJobPkg(item, index) {
  const sd = $getWorkflowStaticData('global');
  const byKey = sd._jobPackagesByKey || {};
  let loopItems = [];
  for (let n = 0; n < LOOP_NAMES.length; n++) {
    try { loopItems = $(LOOP_NAMES[n]).all(); break; } catch (e) {}
  }
  if (typeof index === 'number' && loopItems[index] && loopItems[index].json && loopItems[index].json.job_key) {
    return loopItems[index].json;
  }
  const p = item.pairedItem;
  let idx = null;
  if (Array.isArray(p)) {
    const first = p.find(function (x) { return x && typeof x.item === 'number'; });
    idx = first ? first.item : null;
  } else if (p && typeof p.item === 'number') {
    idx = p.item;
  }
  if (idx !== null && loopItems[idx] && loopItems[idx].json && loopItems[idx].json.job_key) {
    return loopItems[idx].json;
  }
  try {
    const loopItem = $('Loop Over Items1').item;
    if (loopItem && loopItem.json && loopItem.json.job_key) return loopItem.json;
  } catch (e) {}
  const keys = Object.keys(byKey);
  if (keys.length === 1) return byKey[keys[0]];
  return {};
}

function isBccTrackerComplete(val) {
  const s = String(val !== null && val !== undefined ? val : '').trim().toLowerCase();
  if (!s) return false;
  return s === 'complete' || s === 'completed' || s.startsWith('complete');
}

function isQ22Yes(val) {
  const s = String(val !== null && val !== undefined ? val : '').trim().toLowerCase();
  if (!s) return false;
  return s === 'yes' || s === 'y' || /^yes\b/.test(s) || s === 'true';
}

const sd = $getWorkflowStaticData('global');
if (!sd._jobStatusRun) sd._jobStatusRun = { expected: 0, results: [] };
if (!sd._jobStatusResultsByKey) sd._jobStatusResultsByKey = {};

for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const pkg = getJobPkg(item, i);
  if (pkg.job_key && sd._jobPackagesByKey && sd._jobPackagesByKey[pkg.job_key]) {
    Object.assign(pkg, sd._jobPackagesByKey[pkg.job_key]);
  }
  const ai = parseAi(item.json || {});
  // Primary status from EasyBOP Completed date column
  const completedDate = String(pkg.completed_date || '').trim();
  const blockers = pkg.completion_blockers || [];
  const forceIncomplete = blockers.length > 0 || !!pkg.force_incomplete;
  const aiStatus = String(ai.job_status || '').trim().toLowerCase();
  const aiConf = String(ai.completion_confidence || '').trim().toLowerCase();
  const aiScopeComplete = aiStatus === 'completed' && aiConf !== 'low';
  let jobStatus = 'incomplete';
  let statusReason = '';
  let statusConfidence = 'high';
  if (completedDate) {
    jobStatus = 'completed';
    statusReason = 'Works completed date: ' + completedDate;
  } else if (!forceIncomplete && isBccTrackerComplete(pkg.bcc_tracker_status)) {
    const bccLabel = String(pkg.bcc_tracker_status || 'Complete').trim() || 'Complete';
    jobStatus = 'completed';
    statusReason = 'BCC Tracker Status: ' + bccLabel + ' (completed date not set yet)';
    statusConfidence = 'high';
  } else if (!forceIncomplete && aiScopeComplete) {
    jobStatus = 'completed';
    statusReason = 'OJS scope appears complete (no EasyBOP completed date yet): ' + (ai.completion_reason || '');
    statusConfidence = aiConf || 'medium';
  } else {
    jobStatus = 'incomplete';
    statusReason = forceIncomplete
      ? blockers.join('; ')
      : (ai.completion_reason || 'No completed date — job is WIP');
    statusConfidence = forceIncomplete ? 'high' : (aiConf || 'medium');
  }
  const merged = Object.assign({}, pkg, {
    job_status: jobStatus,
    job_status_confidence: statusConfidence,
    job_status_reason: statusReason,
    time_assessment_notes: ai.time_assessment || '',
    uncovered_items: ai.uncovered_boq_items || '',
    ojs_scope_complete: jobStatus === 'completed' && !completedDate,
  });

  const jeopardy = computeJeopardy(merged);
  merged.in_jeopardy = jeopardy.in_jeopardy;
  merged.jeopardy_reason = jeopardy.jeopardy_reason;
  merged._jeopardy = jeopardy;
  merged.processed_via = 'ai';
  merged.processed_via = 'ai';
  if (merged.job_key) {
    sd._jobStatusResultsByKey[merged.job_key] = merged;
  }
}

sd._jobStatusRun.results = Object.values(sd._jobStatusResultsByKey);
const run = sd._jobStatusRun;

return [{
  json: {
    _loop_continue: true,
    batch_processed: $input.all().length,
    total_processed: run.results.length,
    total_expected: run.expected,
  },
}];

// ── Flush row updates (Phase 1) ───────────────────────────────────────────────
// Updates rows for processed jobs only (skips frozen handover jobs).
// Writes Job Status Input Hash for fingerprint tracking.

function norm(v) { return String(v !== null && v !== undefined ? v : '').trim(); }
function normKey(s) { return norm(s).toUpperCase(); }

function jobKeyFromRow(row) {
  const sfn = String(row['SmartForm Name'] || row.smart_form_name || '').trim();
  if (sfn) return normKey(sfn);
  const corf = String(row.CORF || row.corf || '').trim();
  return corf ? 'CORF:' + corf : '';
}

function isHeader(row) {
  return /^smartform name$/i.test(String(row['SmartForm Name'] || row.smart_form_name || '').trim());
}

function parseVisitHours(row) {
  const h = String(row['Q2.1 Daily Jobs Table Price/Hours'] || '').trim();
  const m = h.match(/(\d+(?:\.\d+)?)/);
  return m ? parseFloat(m[1]) : 0;
}

function parseApptDate(s) {
  const t = String(s || '').trim();
  if (!t) return '';
  if (/^\d{4}-\d{2}-\d{2}/.test(t)) return t.slice(0, 10);
  const m = t.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})/);
  if (!m) return '';
  let a = parseInt(m[1], 10), b = parseInt(m[2], 10), y = m[3];
  if (y.length === 2) y = '20' + y;
  y = parseInt(y, 10);
  let mo, day;
  if (a > 12) { day = a; mo = b; }
  else if (b > 12) { mo = a; day = b; }
  else { mo = a; day = b; }
  const pad = function (n) { return n < 10 ? '0' + n : String(n); };
  return y + '-' + pad(mo) + '-' + pad(day);
}

function computeJeopardy(job) {
  if (job.job_status === 'completed') {
    return { in_jeopardy: false, jeopardy_type: '', jeopardy_reason: '' };
  }
  const apptDate = String(job.appointment_date || '').trim();
  if (!apptDate) {
    return { in_jeopardy: false, jeopardy_type: '', jeopardy_reason: '' };
  }
  const today = new Date().toISOString().slice(0, 10);
  const nextApptRaw = String(job.next_appointment_date || '').trim();
  const nextApptBlank = !nextApptRaw;
  const nextApptIso = nextApptRaw ? parseApptDate(nextApptRaw) : '';
  const nextApptPast = !nextApptBlank && nextApptIso && nextApptIso < today;
  if (nextApptBlank || nextApptPast) {
    const reason = nextApptBlank
      ? 'No next appointment date booked — job requires a new appointment'
      : 'Next appointment date (' + nextApptRaw + ') is in the past — requires action';
    return { in_jeopardy: true, jeopardy_type: 'next_appointment_needed', jeopardy_reason: reason };
  }
  const spent = Number(job.time_spent_hours) || 0;
  const allowed = job.smv_allowed_hours != null && job.smv_allowed_hours !== ''
    ? Number(job.smv_allowed_hours)
    : (job.smv_allowed_minutes != null && job.smv_allowed_minutes !== ''
      ? Number(job.smv_allowed_minutes) / 60
      : null);
  if (allowed && allowed > 0 && spent > allowed * 1.05) {
    return {
      in_jeopardy: true,
      jeopardy_type: 'manager_review',
      jeopardy_reason: 'Time spent exceeds SMV allowance (' + spent + 'h vs ' + allowed + 'h)',
    };
  }
  return { in_jeopardy: false, jeopardy_type: '', jeopardy_reason: '' };
}

const ojsItems = $('Read Operative Job Sheet7').all();
const ojsRows = ojsItems.map(function(i) { return i.json || {}; });

const sd = $getWorkflowStaticData('global');
const byKey = sd._jobStatusResultsByKey || {};
const results = Object.values(byKey);
const buildStats = sd._buildStats || {};
const expected = (sd._jobStatusRun && sd._jobStatusRun.expected) || 0;

let completed = 0;
let incomplete = 0;
let jeopardyCount = 0;
let aiProcessed = 0;
let codeProcessed = 0;
for (let i = 0; i < results.length; i++) {
  const j = computeJeopardy(results[i]);
  results[i]._jeopardy = j;
  if (results[i].job_status === 'completed') completed++;
  else incomplete++;
  if (j.in_jeopardy) jeopardyCount++;
  if (results[i].processed_via === 'ai') aiProcessed++;
  else codeProcessed++;
}

sd._jobStatusSummary = {
  jobs_assessed: results.length,
  completed_count: completed,
  incomplete_count: incomplete,
  jeopardy_count: jeopardyCount,
  expected_ai_count: expected,
  skipped_count: buildStats.skipped_count || 0,
  ai_processed_count: aiProcessed,
  code_only_count: codeProcessed,
  total_jobs: buildStats.total_jobs || results.length,
};

const jobResults = {};
for (let i = 0; i < results.length; i++) {
  if (results[i].job_key) jobResults[results[i].job_key] = results[i];
}

const checkedAt = new Date().toISOString();
const updates = [];
for (const row of ojsRows) {
  if (isHeader(row)) continue;
  const rn = row.row_number;
  if (rn === null || rn === undefined || rn === '') continue;
  const job = jobResults[jobKeyFromRow(row)];
  if (!job) continue;
  const notes = [job.job_status_reason, job.uncovered_items].filter(Boolean).join(' | ');
  const jeopardy = job._jeopardy || computeJeopardy(job);
  updates.push({
    json: {
      row_number: rn,
      'Job Status': job.job_status,
      'Job Status Notes': notes,
      'Job Status Confidence': job.job_status_confidence || '',
      'Job Time Spent Hours': job.time_spent_hours,
      'Visit Hours': parseVisitHours(row),
      'Operative Time Breakdown': job.operative_breakdown || '',
      'Job SMV Allowed Hours': job.smv_allowed_hours !== null && job.smv_allowed_hours !== undefined ? job.smv_allowed_hours : '',
      'Job SMV Allowed Minutes': job.smv_allowed_minutes !== null && job.smv_allowed_minutes !== undefined ? job.smv_allowed_minutes : '',
      'Time vs SMV': job.time_assessment_notes || job.time_vs_smv_prelim || '',
      'In Jeopardy': jeopardy.in_jeopardy ? 'Yes' : 'No',
      'Jeopardy Type': jeopardy.jeopardy_type || '',
      'Jeopardy Reason': jeopardy.jeopardy_reason || '',
      'Job Status Checked At': checkedAt,
      'Job Status Input Hash': job.input_fingerprint || '',
    },
  });
}

sd._jobStatusRun = { expected: 0, results: [] };
sd._jobStatusResultsByKey = {};
sd._jobPackagesByKey = {};
sd._buildStats = {};

return updates;

const sd = $getWorkflowStaticData('global');
const summary = sd._jobStatusSummary || {};

let rowsUpdated = 0;
try {
  rowsUpdated = $('Update Operative Job Sheet1').all().length;
} catch (e) {
  try { rowsUpdated = $('Update Operative Job Sheet1').all().length; } catch (e2) {}
}

return [{
  json: {
    message: 'Job status check complete',
    total_jobs: summary.total_jobs || 0,
    jobs_assessed: summary.jobs_assessed || 0,
    skipped_count: summary.skipped_count || 0,
    ai_jobs_queued: summary.expected_ai_count || 0,
    ai_processed_count: summary.ai_processed_count || 0,
    code_only_count: summary.code_only_count || 0,
    completed_count: summary.completed_count || 0,
    incomplete_count: summary.incomplete_count || 0,
    jeopardy_count: summary.jeopardy_count || 0,
    rows_updated: rowsUpdated,
    finished_at: new Date().toISOString(),
  },
}];
